// Some portions generated by Codex
package org.eclipse.rdf4j.common.iteration;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.NoSuchElementException;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

@Execution(ExecutionMode.SAME_THREAD)
class TimeLimitIterationTest {

	@Test
	void closingLastIterationStopsTimerThread() throws InterruptedException {
		TimeLimitIteration<Object> iteration = timedIteration(TimeUnit.DAYS.toMillis(1));
		Thread timerThread = findTimerThread();

		assertNotNull(timerThread);
		iteration.close();
		timerThread.join(TimeUnit.SECONDS.toMillis(1));

		assertFalse(timerThread.isAlive());
	}

	@Test
	void closingOneOfTwoIterationsKeepsTimerUntilLastClose() throws InterruptedException {
		TimeLimitIteration<Object> first = timedIteration(TimeUnit.DAYS.toMillis(1));
		TimeLimitIteration<Object> second = timedIteration(TimeUnit.DAYS.toMillis(1));
		Thread timerThread = findTimerThread();

		assertNotNull(timerThread);
		first.close();
		assertTrue(timerThread.isAlive());

		second.close();
		timerThread.join(TimeUnit.SECONDS.toMillis(1));
		assertFalse(timerThread.isAlive());
	}

	@Test
	void deadlineStillFiresAfterTimerRecreation() throws InterruptedException {
		TimeLimitIteration<Object> first = timedIteration(TimeUnit.DAYS.toMillis(1));
		Thread firstTimerThread = findTimerThread();

		assertNotNull(firstTimerThread);
		first.close();
		firstTimerThread.join(TimeUnit.SECONDS.toMillis(1));
		assertFalse(firstTimerThread.isAlive());

		CloseTrackingIteration delegate = new CloseTrackingIteration();
		TimeLimitIteration<Object> second = timedIteration(delegate, TimeUnit.MILLISECONDS.toMillis(100));
		Thread secondTimerThread = findTimerThread();

		assertNotNull(secondTimerThread);
		assertNotSame(firstTimerThread, secondTimerThread);
		assertTrue(delegate.closed.await(2, TimeUnit.SECONDS));
		secondTimerThread.join(TimeUnit.SECONDS.toMillis(1));
		assertFalse(secondTimerThread.isAlive());
		assertEquals(1, delegate.closeCount.get());
		second.close();
	}

	@Test
	void timeoutReleasesOnlyItsOwnSchedulerLease() throws InterruptedException {
		TimeLimitIteration<Object> guard = timedIteration(TimeUnit.DAYS.toMillis(1));
		Thread timerThread = findTimerThread();

		try {
			CloseTrackingIteration delegate = new CloseTrackingIteration();
			timedIteration(delegate, TimeUnit.MILLISECONDS.toMillis(100));

			assertNotNull(timerThread);
			assertTrue(delegate.closed.await(2, TimeUnit.SECONDS));
			awaitTimerWaitingOrStopped(timerThread);
			assertTrue(timerThread.isAlive());
			assertEquals(1, delegate.closeCount.get());
		} finally {
			guard.close();
		}

		timerThread.join(TimeUnit.SECONDS.toMillis(1));
		assertFalse(timerThread.isAlive());
	}

	private static TimeLimitIteration<Object> timedIteration(long timeLimitMillis) {
		return timedIteration(new EmptyIteration<>(), timeLimitMillis);
	}

	private static TimeLimitIteration<Object> timedIteration(CloseableIteration<Object> delegate,
			long timeLimitMillis) {
		return new TimeLimitIteration<>(delegate, timeLimitMillis) {

			@Override
			protected void throwInterruptedException() {
				throw new AssertionError("unexpected timeout");
			}
		};
	}

	private static Thread findTimerThread() {
		return Thread.getAllStackTraces()
				.keySet()
				.stream()
				.filter(Thread::isAlive)
				.filter(thread -> thread.getName().equals("TimeLimitIteration"))
				.findFirst()
				.orElse(null);
	}

	private static void awaitTimerWaitingOrStopped(Thread timerThread) {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(1);
		while (timerThread.isAlive()
				&& timerThread.getState() != Thread.State.TIMED_WAITING
				&& System.nanoTime() < deadline) {
			Thread.onSpinWait();
		}
	}

	private static final class CloseTrackingIteration implements CloseableIteration<Object> {

		private final CountDownLatch closed = new CountDownLatch(1);
		private final AtomicInteger closeCount = new AtomicInteger();

		@Override
		public void close() {
			closeCount.incrementAndGet();
			closed.countDown();
		}

		@Override
		public boolean hasNext() {
			return false;
		}

		@Override
		public Object next() {
			throw new NoSuchElementException();
		}

		@Override
		public void remove() {
			throw new IllegalStateException();
		}
	}

	private static final long NOT_DURING_THE_TEST = 600_000;

	@Test
	void aFailureOfHasNextCausedByTheTimeLimitIsReportedAsTheTimeLimit() {
		AtomicReference<TimeLimitIteration<String>> limited = new AtomicReference<>();
		CloseableIteration<String> source = new FailingWhenClosedIteration(limited, true);
		limited.set(new TestTimeLimitIteration(source));

		assertThatThrownBy(() -> limited.get().hasNext())
				.isInstanceOf(TimeLimitReached.class)
				.satisfies(failure -> assertThat(failure.getSuppressed())
						.singleElement()
						.isInstanceOf(IllegalStateException.class));
	}

	@Test
	void aFailureOfNextCausedByTheTimeLimitIsReportedAsTheTimeLimit() {
		AtomicReference<TimeLimitIteration<String>> limited = new AtomicReference<>();
		CloseableIteration<String> source = new FailingWhenClosedIteration(limited, false);
		limited.set(new TestTimeLimitIteration(source));

		assertThatThrownBy(() -> limited.get().next()).isInstanceOf(TimeLimitReached.class);
	}

	@Test
	void aFailureBeforeTheTimeLimitIsReportedAsItself() {
		CloseableIteration<String> source = new FailingWhenClosedIteration(new AtomicReference<>(), true);
		try (TimeLimitIteration<String> limited = new TestTimeLimitIteration(source)) {
			assertThatThrownBy(limited::hasNext).isInstanceOf(IllegalStateException.class)
					.hasMessage("closed while computing the next element");
		}
	}

	@Test
	void theTimeLimitClosesTheIterationBeforeReturning() {
		AbstractCloseableIteration<String> source = new AbstractCloseableIteration<>() {
			@Override
			public boolean hasNext() {
				return true;
			}

			@Override
			public String next() {
				return "element";
			}

			@Override
			public void remove() {
				throw new UnsupportedOperationException();
			}

			@Override
			protected void handleClose() {
				// nothing to release
			}
		};
		TimeLimitIteration<String> limited = new TestTimeLimitIteration(source);

		limited.interrupt();

		assertThat(limited.isClosed()).as("the time limit closes the iteration itself").isTrue();
		assertThat(source.isClosed()).as("the time limit closes the wrapped iteration before returning").isTrue();
		assertThatThrownBy(limited::hasNext).isInstanceOf(TimeLimitReached.class);
	}

	/** The time limit's own exception. */
	private static final class TimeLimitReached extends RuntimeException {
		private static final long serialVersionUID = 1L;

		private TimeLimitReached() {
			super("time limit reached");
		}
	}

	private static final class TestTimeLimitIteration extends TimeLimitIteration<String> {

		private TestTimeLimitIteration(CloseableIteration<String> source) {
			super(source, NOT_DURING_THE_TEST);
		}

		@Override
		protected void throwInterruptedException() {
			throw new TimeLimitReached();
		}
	}

	/**
	 * An iteration that is computing its next element when the time limit fires (when {@code limited} is set), and then
	 * fails because it was closed under it, like an evaluation step whose state the close released.
	 */
	private static final class FailingWhenClosedIteration extends AbstractCloseableIteration<String> {

		private final AtomicReference<TimeLimitIteration<String>> limited;

		private final boolean failInHasNext;

		private FailingWhenClosedIteration(AtomicReference<TimeLimitIteration<String>> limited,
				boolean failInHasNext) {
			this.limited = limited;
			this.failInHasNext = failInHasNext;
		}

		@Override
		public boolean hasNext() {
			if (failInHasNext) {
				fail();
			}
			return true;
		}

		@Override
		public String next() {
			fail();
			return "unreachable";
		}

		private void fail() {
			TimeLimitIteration<String> iteration = limited.get();
			if (iteration != null) {
				// The timer fires while this element is computed.
				iteration.interrupt();
			}
			throw new IllegalStateException("closed while computing the next element");
		}

		@Override
		public void remove() {
			throw new UnsupportedOperationException();
		}

		@Override
		protected void handleClose() {
			// nothing to release
		}
	}

}
